import fs from 'node:fs';
import path from 'node:path';
import { inflateRawSync } from 'node:zlib';

const CENTRAL = 0x02014b50;
const LOCAL = 0x04034b50;
const END = 0x06054b50;
const ZIP64 = 0xffffffff;

// Only ZIP features generated by GitHub or Compress-Archive are supported.
// Central-directory metadata is used so data descriptors cannot fool the
// extractor into writing unexpected bytes. Unknown/unsafe files fail closed.
export function unpackZip(archive, destination, {
  maxFiles = 3500, maxBytes = 300 * 1024 * 1024,
  extensions = null,
} = {}) {
  const bytes = Buffer.isBuffer(archive) ? archive : Buffer.from(archive);
  if (bytes.length < 22) throw new Error('ZIP archive is incomplete.');
  let end = -1;
  for (let i = bytes.length - 22; i >= Math.max(0, bytes.length - 65557); i--) {
    if (bytes.readUInt32LE(i) === END &&
        i + 22 + bytes.readUInt16LE(i + 20) === bytes.length) {
      end = i; break;
    }
  }
  if (end < 0) throw new Error('ZIP central directory not found.');
  if (bytes.readUInt16LE(end + 4) || bytes.readUInt16LE(end + 6) ||
      bytes.readUInt16LE(end + 8) !== bytes.readUInt16LE(end + 10))
    throw new Error('Multidisk ZIP is not supported.');
  const count = bytes.readUInt16LE(end + 10);
  const centralSize = bytes.readUInt32LE(end + 12);
  const centralAt = bytes.readUInt32LE(end + 16);
  if (count > maxFiles || centralAt === ZIP64 || centralSize === ZIP64 ||
      centralAt + centralSize > end) throw new Error('Unsupported or oversized ZIP directory.');

  const parent = path.resolve(destination);
  let offset = centralAt, extracted = 0, total = 0;
  for (let n = 0; n < count; n++) {
    if (offset + 46 > bytes.length || bytes.readUInt32LE(offset) !== CENTRAL)
      throw new Error('Malformed ZIP central directory.');
    const flags = bytes.readUInt16LE(offset + 8);
    const method = bytes.readUInt16LE(offset + 10);
    const compressed = bytes.readUInt32LE(offset + 20);
    const expanded = bytes.readUInt32LE(offset + 24);
    const nameLength = bytes.readUInt16LE(offset + 28);
    const extraLength = bytes.readUInt16LE(offset + 30);
    const commentLength = bytes.readUInt16LE(offset + 32);
    const unixMode = (bytes.readUInt32LE(offset + 38) >>> 16) & 0xf000;
    const localOffset = bytes.readUInt32LE(offset + 42);
    const next = offset + 46 + nameLength + extraLength + commentLength;
    if (next > centralAt + centralSize || compressed === ZIP64 || expanded === ZIP64 ||
        localOffset === ZIP64) throw new Error('ZIP entry exceeds supported limits.');
    const rawName = bytes.subarray(offset + 46, offset + 46 + nameLength).toString('utf8');
    // PowerShell Compress-Archive on Windows may store backslash separators.
    // Canonicalize before checking traversal and absolute paths.
    const raw = rawName.replace(/\\/g, '/');
    offset = next;
    if (!raw || raw.includes('\ufffd') || raw.startsWith('/') ||
        raw.includes('\0') || raw.includes(':') || (flags & 1))
      throw new Error('Invalid or encrypted ZIP entry.');
    const pieces = raw.replace(/\/$/, '').split('/');
    if (pieces.some(p => !p || p === '.' || p === '..' || /[<>:"|?*\x00-\x1f]/.test(p)))
      throw new Error('Unsafe ZIP entry path.');
    if (unixMode === 0xa000) continue; // Never follow archive symlinks.
    if (raw.endsWith('/')) continue;
    if (extensions && !extensions.has(path.extname(raw).toLowerCase())) continue;
    if (flags & 0x40 || ![0, 8].includes(method)) throw new Error('Unsupported ZIP compression.');
    total += expanded;
    if (total > maxBytes) throw new Error('ZIP expanded size exceeds safety limit.');
    if (localOffset + 30 > bytes.length || bytes.readUInt32LE(localOffset) !== LOCAL)
      throw new Error('ZIP local entry is invalid.');
    const localName = bytes.readUInt16LE(localOffset + 26);
    const localExtra = bytes.readUInt16LE(localOffset + 28);
    const start = localOffset + 30 + localName + localExtra;
    if (start + compressed > bytes.length) throw new Error('ZIP data is truncated.');
    const input = bytes.subarray(start, start + compressed);
    const data = method === 0 ? input :
      inflateRawSync(input, { maxOutputLength: Math.min(maxBytes, expanded) + 1 });
    if (data.length !== expanded) throw new Error('Invalid uncompressed ZIP length.');
    const output = path.resolve(parent, ...pieces);
    if (!output.startsWith(parent + path.sep)) throw new Error('ZIP escaped its destination.');
    fs.mkdirSync(path.dirname(output), { recursive: true });
    fs.writeFileSync(output, data, { flag: 'wx' });
    extracted++;
  }
  if (offset !== centralAt + centralSize) throw new Error('ZIP directory length mismatch.');
  return { files: extracted, bytes: total };
}
